item.command:
/bin/bash -c "python - <<'PY'
import os, urllib.request, json, time, urllib.error
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); url=os.environ['GALAXY_URL'].rstrip('/')
hid='bbd44e69cb8906b5229eff8e1852b8c4'
for i in range(20):
    try:
        req=urllib.request.Request(url+f'/api/histories/{hid}/contents', headers={'x-api-key':key})
        data=json.load(urllib.request.urlopen(req, timeout=30))
        print('OK attempt',i,'count',len(data))
        for d in data:
            print(d['id'], d['name'], d.get('file_size'), d.get('state'), d.get('genome_build'))
        break
    except Exception as e:
        if isinstance(e, urllib.error.HTTPError):
            body=e.read().decode(errors='replace'); print('ERR',i,body[:100])
        else:
            print('ERR',i,type(e).__name__,e)
        time.sleep(3)
PY"

