/bin/bash -c "python - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
gi=GalaxyInstance(url=os.environ['GALAXY_URL'].rstrip('/'), key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip())
hid='bbd44e69cb8906b56c4e006d78f19fc9'; tool='toolshed.g2.bx.psu.edu/repos/devteam/ncbi_blast_plus/ncbi_makeblastdb/2.16.0+galaxy0'
gid='f9cad7b01a4721357026ebdcad8f37ab'
for keypattern, key in [('underscore','input|selection_0|nuc_choice|source'),('noindex','input|selection|nuc_choice|source')]:
 inp={'input|type':'nucleotide','title':'release6','parse_seqids':True,'hash_index':True}
 inp[key]= 'history'
 inp[key.replace('source','input_file')]={'src':'hda','id':gid}
 try:
  r=gi.tools.build(tool, inputs=inp, history_id=hid)
  print(keypattern, json.dumps(r.get('state_inputs'),indent=2)[:2500])
 except Exception as e:
  print('ERR',keypattern,e)
PY"

